def mfa(iso, name, d, ref, amt, disb, form, note=""):
    dd, mm, yy = d.split(".")
    yy = ("19" + yy if int(yy) > 50 else "20" + yy) if len(yy) == 2 else yy
    P.append([iso, name, f"{yy}-{int(mm):02d}-{int(dd):02d}", "EU macro-financial assistance", form, amt, disb, ref, note, MFA, MFA_URL])
